def is_prime(n):
    if n < 2:
        return False
    for d in range(2, int(n ** 0.5) + 1):
        if n % d == 0:
            return False
    return True

print([n for n in range(1, 31) if is_prime(n)])
print(is_prime(9973), is_prime(9999))
print(is_prime(1), is_prime(2))
